DROP TABLE IF EXISTS `calls`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `calls` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `public_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `chatbot_id` bigint unsigned DEFAULT NULL,
  `lead_id` bigint unsigned NOT NULL,
  `counsellor_id` bigint unsigned DEFAULT NULL,
  `visitor_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direction` enum('OUTBOUND','INBOUND') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OUTBOUND',
  `call_date` date NOT NULL,
  `call_time` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `duration_seconds` int unsigned NOT NULL DEFAULT '0',
  `status` enum('INITIATED','PENDING','SCHEDULED','RINGING','IN_PROGRESS','COMPLETED','MISSED','BUSY','FAILED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INITIATED',
  `outcome` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Interested',
  `provider_call_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recording_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transcript` longtext COLLATE utf8mb4_unicode_ci,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `deleted_by_user_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `public_id` (`public_id`),
  KEY `idx_calls_tenant_counsellor` (`tenant_id`,`counsellor_id`),
  KEY `idx_calls_lead` (`lead_id`),
  KEY `idx_calls_date` (`call_date`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

