DROP TABLE IF EXISTS `chatbot_crawl_jobs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chatbot_crawl_jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `chatbot_id` bigint unsigned NOT NULL,
  `job_type` enum('MANUAL','SCHEDULED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SCHEDULED',
  `dedup_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('PENDING','RUNNING','COMPLETED','UNCHANGED','PARTIAL','FAILED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `locked_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `locked_until` timestamp NULL DEFAULT NULL,
  `attempts` int unsigned NOT NULL DEFAULT '0',
  `max_attempts` int unsigned NOT NULL DEFAULT '3',
  `pages_discovered` int unsigned NOT NULL DEFAULT '0',
  `pages_new` int unsigned NOT NULL DEFAULT '0',
  `pages_changed` int unsigned NOT NULL DEFAULT '0',
  `pages_unchanged` int unsigned NOT NULL DEFAULT '0',
  `pages_removed` int unsigned NOT NULL DEFAULT '0',
  `pages_failed` int unsigned NOT NULL DEFAULT '0',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cb_job_dedup` (`dedup_key`),
  KEY `idx_cb_jobs_claim` (`status`,`locked_until`,`created_at`),
  KEY `idx_cb_jobs_chatbot` (`tenant_id`,`chatbot_id`,`created_at`),
  KEY `fk_cb_crawl_job_chatbot` (`chatbot_id`),
  CONSTRAINT `fk_cb_crawl_job_chatbot` FOREIGN KEY (`chatbot_id`) REFERENCES `chatbots` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_cb_crawl_job_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=876 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
